-- Add only the new field; preserve photos, prices, marks and any manager edits.
begin;
with descriptions(id, description) as (values
('rvb-kitchen-p03-1','Холодная закуска с оригинальной подачей – внутри вафельного стаканчика кремчиз, филе лосося, спелый авокадо и огурец. Сверху на закуске отборная красная икра, подается блюдо с соевый соусом и свежим салатом.'),
('rvb-kitchen-p03-2','Это тонко нарезанный свежий лосось, свежий салат, чипс из пшеничного багета и маринованные каперсы. Подается с соусом из манго и перца чили. Соус довольно сладкий и немного пряный и выгодно подчеркивает вкус свежей рыбы.'),
('rvb-kitchen-p03-3','Хрустящий пшеничный багет, три разные начинки: 1) Ростбиф, томаты черри и сливочный сыр с дижонской горчицей. 2) Лосось собственного посола, оливки, каперсы, сливочный сыр 3) Рулет из цыпленка с грибами, вяленые томаты, микс салатов и сливочный сыр'),
('rvb-kitchen-p04-1','Мелкорубленная говяжья вырезка с добавлением сладкого красного лука, каперсов, и заправкой из соуса ворчестер и пары капель табаско для пикантности. Подается с чипсами из батата, каперсами, томатами черри и дижонской горчицей'),
('rvb-kitchen-p04-2','Филе сельди, подается с маринованными корнишонами, обжаренным бэйби картофелем, красным луком, сметаной и укропом.'),
('rvb-kitchen-p04-3','Универсальная закуска – в ее состав входят: обжаренные креветки, ростбиф, сыры гауда и дор – блю, корнишоны, маслины и томаты черри.'),
('rvb-kitchen-p05-1','Микс салатов ромен и айсберг, нежно обжаренное куриное филе, соус из анчоусов и пармезана, хрустящие гренки, томаты черри и тертый сыр пармезан.'),
('rvb-kitchen-p05-2','Классический домашний оливье с докторской колбасой и красной икрой.'),
('rvb-kitchen-p05-3','Теплый салат со щупальцами кальмара, обжаренным бэйби картофелем, сладким болгарским перцем и томатами черри. Заправляется смесью горчицы и оливкового масла.'),
('rvb-kitchen-p06-3','Микс салатов со свежим манго, клубникой, голубикой и креветками, припущенными в соусе из кокосового молока и пюре манго. Украшается кунжутом.'),
('rvb-kitchen-p06-1','Спелые томаты, хрустящий жареный баклажан, сладкий красный лук, сливочный сыр и кислинка от соуса понзу. Украшается свежей кинзой'),
('rvb-kitchen-p08-1','Нежный ростбиф под соусом из тунца и каперсов, обжаренные мини картофель, баклажан и сладкий перец, свежий огурец, томат черри, микс салатов, заправляется соусом понзу, украшается маринованными каперсами'),
('rvb-kitchen-p07-1','Микс салатов со сладкими томатами черри заправленный соусом блючиз, лосось собственного посола, яйцо пашот.'),
('rvb-kitchen-p08-2','Свежий микс салатов со свежими ягодами – клубника и голубика, спелым авокадо, сегментами апельсина, хрустящими жаренными креветками и лепестками миндаля. Заправляется апельсиновой карамелью.'),
('rvb-kitchen-p07-3','Микс свежих овощей – огурец, томат, сладкий перец, микс салатов, сладкий красный лук, маринованные маслины, брынза, посыпанная сушеным орегано, соус песто и оливковое масло'),
('rvb-kitchen-p07-2','Микс салатов, шляпки шампиньонов фаршированные креветками и сыром моцарелла, сладкие томаты черри, заправка из дижонской горчицы и оливкового масла, слайсы свежего редиса.'),
('rvb-kitchen-p08-3','Микс салатов, свежие томаты и хрустящий огурец, маринованные оливки, куриное яйцо, тунец тиродито (маринованный в соевом соусе тунец, который готовят по методике ошпаривания), заправка «Нисуаз» - оливковое масло, дижоснкая горчица, лимонный сок.'),
('rvb-kitchen-p09-1','Ассорти из сезонных фруктов и ягод, основу закуски составляет ананас, клубника, голубика и апельсин.'),
('rvb-kitchen-p09-2','Нежный ростбиф, свиная грудинка собственного посола, рулет из цыпленка с грибами, копченая индейка, оливки, маслины, маринованный огурец, томаты черри, дижонская горчица, хрен, свежая зелень.'),
('rvb-kitchen-p10-1','Сыр с голубой плесенью, каммамбер, гауда, пармезан, виноград, мед, грецкий орех.'),
('rvb-kitchen-p10-2','Тунец тиродито (маринованный в соевом соусе тунец, который готовят по методике ошпаривания), масляная рыба холодного копчения, лосось собственного посола, сливочное масло, маринованный огурец, красная икра, маслины, лимон.'),
('rvb-kitchen-p11-1','Брускетты на пшеничном багете с нежным ростбифом и сладкими томатами черри, рулет из цыпленка с грибами, рулетики из ветчины с сырно – чесночной начинкой, паштет из тунца на отварных куриный яйцах, томаты фаршированные сырным салатом, докторская колбаса, филе сельди на ржаном хлебе с корнишоном, сыр гауда, маслины, зелень'),
('rvb-kitchen-p11-2','Хрустящие куриные крылья, панированная моцарелла, нежные свиные ребра в соусe медовый BBQ. Картофель фри, чесночные гренки, пряные крокеты из снежного краба с моцареллой, соус спайси, кетчуп, чесночный'),
('rvb-kitchen-p12-1','Большое ассорти на компанию, состоящее из двух видов шашлычков – куриное филе в специях тандури масала и свиная вырезка с копченой паприкой, два вида купат – свиные и куриные, охотнчиьи колбаски, шукрут с беконом, глазированные свиные ребра в соусе BBQ, обжаренный мини – картофель с чесночным маслом, картофельные дольки, соусы BBQ, горчичный, спайси'),
('rvb-kitchen-p13-1','Хрустящие драники со сметаной, икрой (жареным беконом, грибами в сливочном соусе, лососем собственного посола) с зеленым луком.'),
('rvb-kitchen-p13-2','Багет с пряной колбасой пепперони, запеченным куриным филе, ветчиной из индейки, томатами черри, моцареллой и острой горчицей. Украшается мелкорубленным маринованным огурцом.'),
('rvb-kitchen-p15-1','Фаршированные моцареллой и икрой тобико мидии киви, запеченые с соусом терияки.'),
('rvb-kitchen-p15-2','Арабская пицца – пиде, которую мы готовим на сливочным соусе с креветками, лососем, молодым сыром и фисташками. Украшаем рукколой и поливаем оливковым маслом.'),
('rvb-kitchen-p15-3','Арабская пицца – пиде, которую мы готовим на томатным пряном соусе с говяжьим фаршем со специями и красным репчатым луком, запекаем с сыром моцарелла и томатами черри. При подаче украшаем кинзой'),
('rvb-kitchen-p16-1','Пряный тайский суп на рыбном бульоне с лемонрассом и имбирем, креветками, лососем и мидиями киви. Подается с азиатским рисом и перцем чили.'),
('rvb-kitchen-p16-2','Наваристый, домашний борщ сваренный на говяжьем бульоне. Подаем с гренками из бородинского хлеба, грудинкой собственного посола, сметаной и зеленью'),
('rvb-kitchen-p17-1','Паста фетучини в сливочном соусе с орегано, стейк из лосося, обжаренный на гриле, отварные брокколи, пармезан'),
('rvb-kitchen-p17-2','Это гречневая лапша с креветками, щупальцами кальмара, цукини, сладим перцем, репчатым луком, соусом унаги, терияки и кинжутным маслом. Подается со слайсами перца чили и кинзой'),
('rvb-kitchen-p17-3','Сливочно – сырная паста лингвини с соком свеклы, в составе соуса моцарелла и пармезан, обжаренные креветки на гриле, микс салата.'),
('rvb-kitchen-p18-3','Спагетти с чернилами каракатицы с соусом сливочный том ям, с креветками, жаренными на гриле, томатами черри, кинзой, соусом терияки и кунжутом.'),
('rvb-kitchen-p18-1','Спагетти на соусе их желтков, сливок и пармезана с беконом. Украшается чипсами из бекона и тертым пармезаном'),
('rvb-kitchen-p18-2','Пшеничная лапша удон с филе индейки, баклажаном, цукини, сладким перцем, морковью в соусе унаги – кунжутное масло. Подается с слайсами перца чили и кинзой'),
('rvb-kitchen-p19-1','Бургер с говяжьей котлетой, пряным соусом спайси, жареным беконом, томатами и горчичным соусом и сыром чеддер'),
('rvb-kitchen-p19-2','Бургер с нежной куриной котлетой, соусом карри, жаренным беконом, томатами и сыром чеддер'),
('rvb-kitchen-p20-1','Запеченное филе окуня под соусом айоли – соус из желтков, оливкового масла и чеснока, на подушке из овощей - цукини, баклажан и томат с соусом пилати и оливковым маслом.'),
('rvb-kitchen-p20-2','Исконно белорусское блюдо – мачанку мы готовим из свиных ребер, куриных купат, лука, чеснока, молока и муки. Подаем с чипсами из бекона и луком фри.'),
('rvb-kitchen-p20-3','Филе лосося мы предварительно обжариваем до хрустящей корочки, затем выкладываем на подушку из грибного соуса застилаем печеным картофелем, посыпаем сыром моцарелла и запекаем. Подаем с луком фри и долькой лимона'),
('rvb-kitchen-p21-1','Нежная говяжья вырезка, которую мы маринуем с тимьяном и розмарином мы обжариваем на гриле до прожарки медиум. Подаем с запеченным чесноком, крупной морской солью и соусом на выбор – горчичным, мясным или грибным.'),
('rvb-kitchen-p23-1','Запеченое филе лосося на подушке из пюре брокколи, украшается припущенными брокколи, красно икрой и шафрановым соусом.'),
('rvb-kitchen-p22-2','Свиные купаты обжаренные на гриле, подаются с молодым картофелем обжаренным с чесноком, тушеной с беконом капустой и соусом BBQ'),
('rvb-kitchen-p22-3','Индейка в тайском соусе, обжаренная с баклажаном, луком, морковью и цукини, с хрустящим картофелем фри, перцем чили и кунжутом'),
('rvb-kitchen-p25-1','Альтернативный отруб премиальной говядины, который мы маринуем в течении 48 часов, обжаренный на гриле. Подается только в прожарке от медиум велл. Подаем с запеченым чесноком, крупной морской солью и соусом на выбор – мясным, горчичным или грибным'),
('rvb-kitchen-p24-1','Отбивная из свиной вырезки с шампиньонными и томатами, запеченая под горчично – майонезно – сырной шапкой, подаем с молодым картофелем, обжаренным с чесноком и миксом салата.'),
('rvb-kitchen-p24-2','Томленые 24 часа в крепком говяжьем бульоне с красным вином говяжьи щеки, подаются с нежным картофельным пюре, мясным соусом и малосольными огурцами.'),
('rvb-kitchen-p24-3','Куриные колбаски обжаренные на гриле с картофелем по деревенски, тушеной с беконом квашеной капустой и острой горчицей.'),
('rvb-kitchen-p22-1','Стейк из филе индейки с соусом из грибов и чипсами из бекона. Подается с маринованным огурцом.'),
('rvb-kitchen-p26-1','Нежная говяжья вырезка обжаренная с луком и шампиньонами в сливочно – горчичном соусе, подается с картофельным пюре, маринованными огурцами и маринованными томатами черри.')
), updated as (
update public.academy_content c set payload=jsonb_set(c.payload,'{vividDescription}',to_jsonb(d.description),true) from descriptions d where c.id=d.id and c.kind='menu' and c.payload->>'menuSection'='kitchen' and not(c.payload ? 'vividDescription') returning c.id
) select count(*) as descriptions_added from updated;
commit;
select count(*) as descriptions_available from public.academy_content where kind='menu' and payload->>'menuSection'='kitchen' and coalesce(payload->>'vividDescription','')<>'';
